import csv,json,collections,pathlib
root=pathlib.Path(__file__).resolve().parents[1];rows=list(csv.DictReader(open(root/'data/roster/nominees_audited.csv')));g=collections.defaultdict(list)
for r in rows:g[r['race_id']].append(r)
polls=json.load(open(root/'data/signals/polls_2026.json')); out={}; clerk=rows[0]['source_url']
def add(k,a,b,kind,reason,system='plurality',sources=None,aliases=None):
 field=g[k];names=[r['name'] for r in field];assert a is None or a in names,(k,a);assert b is None or b in names,(k,b)
 out[k]=dict(candidate_a=a,candidate_b=b,kind=kind,other_candidates=[x for x in names if x not in (a,b)],candidate_parties={r['name']:r['party_label'] for r in field},reason=reason,source_urls=[clerk]+(sources or []),electoral_system=system,caucus_assumption=None,poll_aliases=aliases or {})
