add('NE-SEN','Dan Osborn','Pete Ricketts','independent_principal_challenger','No Democratic printed nominee. Osborn is By Petition independent. Marvin suspended campaign but remains printed on ballot; no caucus assumption.',sources=['https://netchoice.org/netchoice-echelon-insights-poll-voters-rank-ai-regulation-far-behind-cost-of-living-want-one-national-ai-standard/'])
add('SD-SEN','Brian L. Bengs','Mike Rounds','independent_principal_challenger','Official source marks Beaudion withdrawn; Bengs and Rounds active. No caucus assumption.',sources=['https://vip.sdsos.gov/candidatelist.aspx?eid=774'],aliases={'Brian L. Bengs':['Brian Bengs']})
