for k in [f'LA-{i:02}' for i in range(1,7)]:
 v=g[k];ds=[x['name'] for x in v if x['party_label'].startswith('Democrat')];rs=[x['name'] for x in v if x['party_label'].startswith('Republican')];a=ds[0] if len(ds)==1 else None;b=next((x['name'] for x in v if x['incumbent']=='true' and x['party_label'].startswith('Republican')),None) or (rs[0] if len(rs)==1 else None);add(k,a,b,'all_party_primary_runoff','November all-party election followed by December runoff if no majority. Multiple same-party candidates retained; null pair side means no uniquely established nominee. Must model full field and eventual runoff winner.','majority_runoff',sources=['https://www.sos.la.gov/OurOffice/PublishedDocuments/05.14.26FallHouseRaces.pdf'])
